import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';

const matchingMigrationNames = readdirSync('supabase/migrations')
  .filter((name) => name.endsWith('_user_consent.sql'))
  .sort((left, right) => left.localeCompare(right));

assert.ok(
  matchingMigrationNames.length > 0,
  'user consent migration must be generated by the Supabase CLI',
);

const migrationName = matchingMigrationNames.at(-1);
assert.ok(
  migrationName,
  'user consent migration selection must resolve to the newest matching file',
);

const migration = readFileSync(`supabase/migrations/${migrationName}`, 'utf8');
const prisma = readFileSync('apps/api/prisma/schema.prisma', 'utf8');
const insertPolicyMatch = migration.match(
  /CREATE POLICY "user_consent_insert_current"[\s\S]*?WITH CHECK \(([\s\S]*?)\);/,
);
assert.ok(insertPolicyMatch, 'user consent insert policy must exist');

const insertPolicy = insertPolicyMatch[1];
const insertPolicySourceListMatch = insertPolicy.match(/source IN \(([^)]+)\)/);
assert.ok(
  insertPolicySourceListMatch,
  'user consent insert policy must constrain the allowed source values',
);

const insertPolicySources = [...insertPolicySourceListMatch[1].matchAll(/'([^']+)'/g)].map(
  ([, source]) => source,
);
const userConsentModelMatch = prisma.match(/model UserConsent \{[\s\S]*?\n\}/);
assert.ok(userConsentModelMatch, 'Prisma schema must define model UserConsent');

const userConsentModel = userConsentModelMatch[0];

assert.match(migration, /CREATE TABLE public\."UserConsent"/);
assert.match(migration, /UNIQUE \("userId", "consentVersion"\)/);
assert.match(migration, /ALTER TABLE public\."UserConsent" ENABLE ROW LEVEL SECURITY/);
assert.match(migration, /CREATE POLICY "user_consent_select_own"/);
assert.match(migration, /CREATE POLICY "user_consent_insert_current"/);
assert.match(
  insertPolicy,
  /"consentVersion"\s*=\s*'2026-07-10'/,
  'user consent insert policy must pin consentVersion to 2026-07-10',
);
assert.match(
  insertPolicy,
  /"privacyPolicyVersion"\s*=\s*'2026-07-10'/,
  'user consent insert policy must pin privacyPolicyVersion to 2026-07-10',
);
assert.match(
  insertPolicy,
  /"eulaType"\s*=\s*'apple_standard'/,
  'user consent insert policy must pin eulaType to apple_standard',
);
assert.match(
  insertPolicy,
  /"healthDataProcessingAccepted"(?:\s*=\s*true)?/,
  'user consent insert policy must require healthDataProcessingAccepted to be true',
);
assert.deepEqual(insertPolicySources, [
  'ios_email',
  'ios_apple',
  'ios_google',
  'ios_existing_user',
]);
assert.match(migration, /GRANT SELECT ON TABLE public\."UserConsent" TO authenticated/);
assert.match(
  migration,
  /GRANT INSERT \("userId", "consentVersion", "privacyPolicyVersion", "eulaType", "healthDataProcessingAccepted", source\) ON TABLE public\."UserConsent" TO authenticated/,
);
assert.doesNotMatch(migration, /GRANT (UPDATE|DELETE)/);
assert.doesNotMatch(migration, /SECURITY DEFINER/);
assert.match(migration, /REVOKE ALL ON TABLE public\."UserConsent" FROM PUBLIC/);
assert.match(migration, /REVOKE ALL ON TABLE public\."UserConsent" FROM anon/);
assert.match(prisma, /consents\s+UserConsent\[\]/);
assert.match(
  userConsentModel,
  /user User @relation\(fields: \[userId\], references: \[id\], onDelete: Cascade\)/,
);

console.log('HealthFolio consent migration contract tests passed.');
